import { PALETTE } from './palette.js';

const WAYPOINTS = [
  new THREE.Vector3(0, 0, 10),
  new THREE.Vector3(-6, 0, 4),
  new THREE.Vector3(6, 0, 4),
  new THREE.Vector3(-8, 0, -6),
  new THREE.Vector3(8, 0, -6),
