    get phase() { return phase; },
    get roundTimer() { return roundTimer; },
    get freezeTimer() { return freezeTimer; },
    addMoney(amount) {
      playerMoney += amount;
    },
    spendMoney(amount) {
      if (playerMoney >= amount) {
        playerMoney -= amount;
        return true;
      }
      return false;
    },
    step(dt, onRoundEnd) {
      if (phase === 'buy') {
        freezeTimer -= dt;
        if (freezeTimer <= 0) {
          phase = 'active';
        }
      } else if (phase === 'active') {
        roundTimer -= dt;
